use serde_json::{json,Value};use sha2::{Sha256,Digest};use std::{fs,path::{Path,PathBuf},collections::BTreeMap,process::Command,fmt::Write};
const R:&str="/home/ubuntu/src/zopro-perf-work/glv-kh-borrowed175";
const D:&str="/home/ubuntu/src/zk-tools/zopro/docs/benchmarks/2026-10-29-glv-kh-borrowed175";
fn r(p:impl AsRef<Path>)->PathBuf{Path::new(R).join(p)}fn read(p:impl AsRef<Path>)->Value{serde_json::from_slice(&fs::read(p).unwrap()).unwrap()}fn hash(p:impl AsRef<Path>)->String{format!("{:x}",Sha256::digest(fs::read(p).unwrap()))}
fn member(p:&Path)->Value{let b=fs::read(p).unwrap();let h=format!("{:x}",Sha256::digest(&b));match String::from_utf8(b.clone()){Ok(s)=>json!({"sha256":h,"encoding":"utf8","data":s}),Err(_)=>json!({"sha256":h,"encoding":"hex","data":b.iter().map(|v|format!("{v:02x}")).collect::<String>()})}}
fn collect(root:&Path,dir:&Path,out:&mut BTreeMap<String,Value>){for e in fs::read_dir(dir).unwrap(){let p=e.unwrap().path();if p.is_dir(){collect(root,&p,out)}else{out.insert(p.strip_prefix(root).unwrap().display().to_string(),member(&p));}}}
fn archive(name:&str,members:&BTreeMap<String,Value>,dest:&Path){let b=serde_json::to_vec(members).unwrap();let temp=r(format!("{name}.json"));fs::write(&temp,&b).unwrap();let gz=Command::new("gzip").args(["-n","-c"]).arg(&temp).output().unwrap();assert!(gz.status.success());let p=dest.join(format!("{name}.json.gz"));fs::write(&p,gz.stdout).unwrap();let back=Command::new("gzip").arg("-dc").arg(&p).output().unwrap();assert!(back.status.success());assert_eq!(back.stdout,b);let decoded:BTreeMap<String,Value>=serde_json::from_slice(&back.stdout).unwrap();for(_,record)in decoded{let text=record["data"].as_str().unwrap();let bytes=if record["encoding"]=="utf8"{text.as_bytes().to_vec()}else{assert_eq!(text.len()%2,0);(0..text.len()).step_by(2).map(|i|u8::from_str_radix(&text[i..i+2],16).unwrap()).collect()};assert_eq!(format!("{:x}",Sha256::digest(&bytes)),record["sha256"]);}}

